def bin_counts(rets, edges):
    k = len(edges) - 1
    counts = [0] * k
    for x in rets:
        if x < edges[0] or x > edges[-1]:
            continue
        if x == edges[-1]:
            counts[k - 1] = counts[k - 1] + 1
            continue
        for i in range(k):
            if edges[i] <= x < edges[i + 1]:
                counts[i] = counts[i] + 1
                break
    return counts

