def bin_counts(rets, edges):
    k = len(edges) - 1
    counts = [0] * k
    for x in rets:
        if x >= edges[-1]:
            counts[k - 1] = counts[k - 1] + 1
            continue
        if x < edges[0]:
            counts[0] = counts[0] + 1
            continue
